 p=verify();r=read(P/'SELECTED_FIVE_ROW_RESULTS_PUBLIC.json');selection=read(P/'SELECTION_PUBLIC.json');assert read(P/'SELECTED_ROOT_AUDIT_PUBLIC.json')['status']=='pass';ledger=read(D/'GPU_LEDGER.json');export=P/'all_parameter_outcomes';export.mkdir(exist_ok=True);index=[];totalparents=totalreadouts=0
