 total=dict(new_primary_fits=sum(x['new_primary_fits']for x in ledger['invocations']),new_updates_including_compatibility=sum(x['new_updates']for x in ledger['invocations']),compatibility_updates=sum(x['compatibility_updates']for x in ledger['invocations']),worker_wall_seconds=sum(x['wall_seconds']for x in ledger['invocations']),new_RGB_Source_encoder_forwards=sum(x['new_RGB_or_Source_encoding_forwards']for x in ledger['invocations']),new_expert_forwards=sum(x['new_expert_forwards']for x in ledger['invocations']))
